struct point { int x, y; };
struct shape { struct point corner; int kind; double scale; };

int counter = 5;
static int table[8] = {3, 1, 4, 1, 5, 9, 2, 6};
static const short weights[4] = {-2, 300, -32768, 7};
const char *message = "hello, mips";
static const char escaped[] = "tab\there \"quoted\" \\ end\n";
char buffer[16];
struct shape shapes[3] = {{{1, 2}, 0, 1.5}, {{3, 4}, 1, 2.0}, {{5, 6}, 2, 0.25}};
float ratio = 0.75f;

__attribute__((noinline)) int fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }

__attribute__((noinline)) int length(const char *s) {
    int n = 0;
    while (s[n]) n++;
    return n;
}

__attribute__((noinline)) int classify(int kind, int value) {
    switch (kind) {
    case 0: return value + 1;
    case 1: return value * 3;
    case 2: return value - 7;
    case 3: return value / 2;
    case 4: return value << 2;
    case 5: return -value;
    case 6: return value ^ 0x55;
    default: return 0;
    }
}

__attribute__((noinline)) int divide(int a, int b) { return a / b + a % b; }

__attribute__((noinline)) unsigned udivide(unsigned a, unsigned b) { return a / b + a % b; }

__attribute__((noinline)) double area(const struct shape *s) {
    double w = s->corner.x * s->scale, h = s->corner.y * s->scale;
    return w * h;
}

__attribute__((noinline)) float halve(float f) { return f / 2.0f + ratio; }

__attribute__((noinline)) long long mix(long long a, long long b) {
    return (a * b) + (a >> 3) - (b << 5) + (a ^ b);
}

__attribute__((noinline)) long long shift(long long a, int n) { return (a << n) | ((unsigned long long)a >> (n + 1)); }

static int add3(int v) { return v + 3; }
static int sub2(int v) { return v - 2; }
int (*const operations[2])(int) = {add3, sub2};

__attribute__((noinline)) int apply(int which, int v) { return operations[which & 1](v); }

int main(void) {
    int sum = 0;
    for (int i = 0; i < 8; i++) sum += table[i] * (i + 1);
    for (int i = 0; i < 4; i++) sum += weights[i];
    sum += fib(10);
    sum += length(message) + length(escaped);
    for (int i = 0; i < 12; i++) buffer[i] = message[i];
    sum += buffer[4] == 'o' ? 100 : 0;
    for (int k = 0; k < 8; k++) sum += classify(k, 10 + k);
    sum += divide(-47, 5) + divide(47, -5) + (int)udivide(4000000000u, 7u);
    double total = 0;
    for (int i = 0; i < 3; i++) total += area(&shapes[i]);
    sum += (int)(total * 4);
    if (total > 10.0) sum += 1000;
    if (total < 1.0) sum += 2000;
    sum += (int)(halve(9.0f) * 8.0f);
    long long m = mix(123456789LL, -98765LL);
    sum += (int)(m ^ (m >> 32)) & 0xffff;
    long long s = shift(0x123456789abcLL, counter);
    sum += (int)(s >> 20) & 0xfff;
    sum += apply(0, 40) + apply(1, 40);
    counter = sum;
    return counter;
}
